  # hnswlib, the router's memory, is an extra the formula leaves out: it would
  # compile C++ on every install, and the audit never uses it.
  def install
    virtualenv_install_with_resources
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/mahoraga version")
    assert_match "Usage", shell_output("#{bin}/mahoraga --help")

    # The release sdist carries the built web UI and the bundled data.
    package = libexec/Language::Python.site_packages("python3.14")/"backend/orchestrator"
    assert_path_exists package/"service/ui/index.html"
    assert_path_exists package/"audit/pricing.json"

    port = free_port
    pid = spawn bin/"mahoraga", "serve", "--port", port.to_s
    begin
      health = ""
      30.times do
        sleep 1
        health = Utils.popen_read("curl", "--silent", "--max-time", "2", "http://127.0.0.1:#{port}/api/health")
        break unless health.empty?
      end
      assert_match "\"status\":\"ok\"", health
    ensure
      Process.kill("TERM", pid)
      Process.wait(pid)
    end
  end
